DELETE FROM public.mml_command_sub_fields csf
USING tmp_mml_direct_standard_sub_fields_down i
JOIN public.mml_commands c
  ON c.command_code = i.command_code
JOIN public.standard_params sp
  ON sp.standard_path = i.standard_path
WHERE csf.command_id = c.id
  AND csf.standard_path_id = sp.id;
